const NF = [
  ['KMnO<sub>4</sub> in acidic medium (to Mn<sup>2+</sup>)', 5, 'Mn goes from +7 to +2', 158], ['KMnO<sub>4</sub> in neutral medium (to MnO<sub>2</sub>)', 3, 'Mn goes from +7 to +4', 158],
  ['KMnO<sub>4</sub> in strongly basic medium (to MnO<sub>4</sub><sup>2-</sup>)', 1, 'Mn goes from +7 to +6', 158], ['K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub> in acid (to Cr<sup>3+</sup>)', 6, 'two Cr go from +6 to +3: 2 &times; 3', 294],
  ['H<sub>2</sub>C<sub>2</sub>O<sub>4</sub> (to CO<sub>2</sub>)', 2, 'two C go from +3 to +4', 90], ['FeSO<sub>4</sub> (to Fe<sup>3+</sup>)', 1, 'Fe goes from +2 to +3', 152],
  ['FeC<sub>2</sub>O<sub>4</sub> (to Fe<sup>3+</sup> and CO<sub>2</sub>)', 3, 'Fe: +2 to +3 (1) and two C: +3 to +4 (2)', 144], ['Na<sub>2</sub>S<sub>2</sub>O<sub>3</sub> (to Na<sub>2</sub>S<sub>4</sub>O<sub>6</sub> by iodine)', 1, 'two S<sub>2</sub>O<sub>3</sub><sup>2-</sup> give up 2 e<sup>-</sup>, so 1 each', 158],
  ['H<sub>2</sub>O<sub>2</sub> (to O<sub>2</sub>)', 2, 'two O go from -1 to 0', 34], ['As<sub>2</sub>S<sub>3</sub> (to AsO<sub>4</sub><sup>3-</sup> and SO<sub>4</sub><sup>2-</sup>)', 28, 'As: 2 &times; 2 = 4; S: 3 &times; 8 = 24', 246],
];

export default {
  topic: 'redox',
  groups: {
    m1: { title: 'Match the species with the oxidation number of the stated atom', list1: ['A. S in S<sub>4</sub>O<sub>6</sub><sup>2-</sup> (average)', 'B. Cr in CrO<sub>5</sub>', 'C. Fe in Fe<sub>3</sub>O<sub>4</sub> (average)', 'D. O in KO<sub>2</sub>'], list2: ['p. +6', 'q. +5/2', 'r. +8/3', 's. -1/2'] },
    m2: { title: 'Match the oxidant or reductant with its n-factor (electrons exchanged per formula unit)', list1: ['A. KMnO<sub>4</sub> in acid, to Mn<sup>2+</sup>', 'B. K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub> in acid, to Cr<sup>3+</sup>', 'C. KMnO<sub>4</sub> in neutral solution, to MnO<sub>2</sub>', 'D. FeSO<sub>4</sub>, to Fe<sup>3+</sup>'], list2: ['p. 5', 'q. 6', 'r. 3', 's. 1'] },
    m3: { title: 'Match the type of reaction with an example', list1: ['A. Disproportionation', 'B. Comproportionation', 'C. Displacement', 'D. Intramolecular redox'], list2: ['p. Zn + CuSO<sub>4</sub> &rarr; ZnSO<sub>4</sub> + Cu', 'q. 2H<sub>2</sub>O<sub>2</sub> &rarr; 2H<sub>2</sub>O + O<sub>2</sub>', 'r. IO<sub>3</sub><sup>-</sup> + 5I<sup>-</sup> + 6H<sup>+</sup> &rarr; 3I<sub>2</sub> + 3H<sub>2</sub>O', 's. 2KClO<sub>3</sub> &rarr; 2KCl + 3O<sub>2</sub>'] },
    m4: { title: 'Match the titration with its end-point fact', list1: ['A. KMnO<sub>4</sub> with oxalic acid in hot dilute H<sub>2</sub>SO<sub>4</sub>', 'B. Iodine with sodium thiosulfate', 'C. K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub> with Fe<sup>2+</sup>', 'D. KMnO<sub>4</sub> with Fe<sup>2+</sup> in HCl'], list2: ['p. KMnO<sub>4</sub> is its own indicator: first permanent pale pink', 'q. Starch is added near the end and the blue colour disappears', 'r. Needs an indicator such as diphenylamine (colour change to violet)', 's. Gives too high a result because Cl<sup>-</sup> is also oxidised'] },
    p1: { title: 'Purity of sodium oxalate by permanganate', passage: '<p>A 0.335 g sample of impure sodium oxalate (Na<sub>2</sub>C<sub>2</sub>O<sub>4</sub>, molar mass 134 g mol<sup>-1</sup>) is dissolved in dilute sulfuric acid, warmed, and titrated with 0.0200 M KMnO<sub>4</sub>. The end point needs 40.0 mL. The impurities do not react.</p>' },
    p2: { title: 'Copper in an ore by iodometry', passage: '<p>0.500 g of a copper ore is dissolved in acid and excess KI is added: 2Cu<sup>2+</sup> + 4I<sup>-</sup> &rarr; 2CuI + I<sub>2</sub>. The iodine set free is titrated with 0.100 M sodium thiosulfate: I<sub>2</sub> + 2S<sub>2</sub>O<sub>3</sub><sup>2-</sup> &rarr; 2I<sup>-</sup> + S<sub>4</sub>O<sub>6</sub><sup>2-</sup>. The end point needs 25.0 mL. (Cu = 63.5)</p>' },
    p3: { title: 'Chlorine in alkali', passage: '<p>Chlorine reacts with cold dilute sodium hydroxide to give a solution of two chlorine-containing salts. With hot concentrated sodium hydroxide, a different pair is formed: 3Cl<sub>2</sub> + 6OH<sup>-</sup> &rarr; 5Cl<sup>-</sup> + ClO<sub>3</sub><sup>-</sup> + 3H<sub>2</sub>O.</p>' },
  },
  items: [
    // ---------- Level 1 ----------
    nat('rx-001', 1, 'oxidation number', 'Find the oxidation number of manganese in KMnO<sub>4</sub>.', 7, 0, '', '<p>K is +1 and each O is -2. The compound is neutral: (+1) + x + 4(-2) = 0, so x = <b>+7</b>.</p>', '', () => 8 - 1),
    mk('rx-002', 1, 'oxidation and reduction', 'Oxidation is defined as', 'loss of electrons, or an increase in oxidation number', ['gain of electrons', 'a decrease in oxidation number', 'addition of hydrogen only'], '<p>Remember OIL RIG: Oxidation Is Loss, Reduction Is Gain of electrons. Oxidation raises the oxidation number; reduction lowers it.</p>'),
    nat('rx-003', 1, 'oxidation number', 'Find the oxidation number of sulphur in H<sub>2</sub>SO<sub>4</sub>.', 6, 0, '', '<p>2(+1) + x + 4(-2) = 0 gives x = <b>+6</b>.</p>', '', () => 8 - 2),
    mk('rx-004', 1, 'oxidising and reducing agents', 'In Zn + Cu<sup>2+</sup> &rarr; Zn<sup>2+</sup> + Cu, the oxidising agent is', 'Cu<sup>2+</sup>', ['Zn', 'Zn<sup>2+</sup>', 'Cu'], '<p>An oxidising agent takes electrons and is itself reduced. Cu<sup>2+</sup> gains 2 e<sup>-</sup> to become Cu. Zn loses electrons, so Zn is the reducing agent.</p>'),
    mk('rx-005', 1, 'oxidation number rules', 'The oxidation number of oxygen in H<sub>2</sub>O<sub>2</sub> is', '-1', ['-2', '0', '+1'], '<p>H<sub>2</sub>O<sub>2</sub> is a peroxide containing an O-O bond. Each H is +1, so 2(+1) + 2x = 0 gives x = -1.</p>'),
    mk('rx-006', 1, 'oxidising and reducing agents', 'A reducing agent is a substance that', 'loses electrons and is itself oxidised', ['gains electrons and is itself reduced', 'gains electrons and is itself oxidised', 'does not take part in the reaction'], '<p>A reducing agent reduces something else by giving it electrons, so its own oxidation number increases (it is oxidised).</p>'),
    mk('rx-007', 1, 'oxidation number', 'The oxidation number of chromium in K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub> is', '+6', ['+3', '+7', '+12'], '<p>2(+1) + 2x + 7(-2) = 0 gives 2x = 12, so x = +6. (+12 is the total for two Cr atoms, not each.)</p>'),
    mk('rx-008', 1, 'oxidation number rules', 'In CaH<sub>2</sub> the oxidation number of hydrogen is', '-1', ['+1', '0', '+2'], '<p>In metal hydrides hydrogen is more electronegative than the metal and takes -1. Ca is +2, so 2 H must total -2.</p>', 'H is +1 only when combined with non-metals.'),
    mk('rx-009', 1, 'redox reactions', 'Which of the following is a redox reaction?', 'Zn + H<sub>2</sub>SO<sub>4</sub> &rarr; ZnSO<sub>4</sub> + H<sub>2</sub>', ['NaOH + HCl &rarr; NaCl + H<sub>2</sub>O', 'AgNO<sub>3</sub> + KCl &rarr; AgCl + KNO<sub>3</sub>', 'BaCl<sub>2</sub> + Na<sub>2</sub>SO<sub>4</sub> &rarr; BaSO<sub>4</sub> + 2NaCl'], '<p>A redox reaction changes oxidation numbers. In Zn + H<sub>2</sub>SO<sub>4</sub>, Zn goes 0 to +2 and H goes +1 to 0. The other three are neutralisation or precipitation; no oxidation number changes.</p>'),
    mk('rx-010', 1, 'oxidation number rules', 'The oxidation number of an atom in its elemental form (for example in O<sub>2</sub>, P<sub>4</sub>, S<sub>8</sub>) is', 'zero', ['+1', '-1', 'equal to its valency'], '<p>Atoms of the same element share electrons equally, so there is no charge shift: oxidation number 0.</p>'),
    mk('rx-011', 1, 'oxidation and reduction', 'In the reaction Fe<sup>3+</sup> + e<sup>-</sup> &rarr; Fe<sup>2+</sup>, the iron ion is', 'reduced', ['oxidised', 'neither oxidised nor reduced', 'a reducing agent'], '<p>It gains an electron, and its oxidation number falls from +3 to +2: reduction. Fe<sup>3+</sup> is acting as an oxidising agent.</p>'),
    mk('rx-012', 1, 'oxidising power', 'Which halogen is the strongest oxidising agent?', 'F<sub>2</sub>', ['Cl<sub>2</sub>', 'Br<sub>2</sub>', 'I<sub>2</sub>'], '<p>Oxidising power decreases down the group: F<sub>2</sub> (E&deg; = +2.87 V) &gt; Cl<sub>2</sub> (+1.36 V) &gt; Br<sub>2</sub> (+1.09 V) &gt; I<sub>2</sub> (+0.54 V).</p>'),

    // ---------- Level 2 ----------
    nat('rx-013', 2, 'average oxidation number', 'Find the average oxidation number of iron in Fe<sub>3</sub>O<sub>4</sub>.', 2.67, 0.01, '', '<p>3x + 4(-2) = 0 gives x = 8/3 = <b>2.67</b>. In reality Fe<sub>3</sub>O<sub>4</sub> is FeO&middot;Fe<sub>2</sub>O<sub>3</sub>: one Fe(+2) and two Fe(+3), averaging 8/3.</p>', '', () => 8 / 3),
    mk('rx-014', 2, 'oxidation number', 'The oxidation number of chlorine in ClO<sub>3</sub><sup>-</sup> is', '+5', ['+3', '+6', '+7'], '<p>The ion has charge -1: x + 3(-2) = -1 gives x = +5. (Perchlorate ClO<sub>4</sub><sup>-</sup> would be +7.)</p>'),
    mk('rx-015', 2, 'disproportionation', 'Which of the following is a disproportionation reaction?', 'Cl<sub>2</sub> + 2NaOH &rarr; NaCl + NaClO + H<sub>2</sub>O', ['2KClO<sub>3</sub> &rarr; 2KCl + 3O<sub>2</sub>', 'Zn + CuSO<sub>4</sub> &rarr; ZnSO<sub>4</sub> + Cu', 'NaOH + HCl &rarr; NaCl + H<sub>2</sub>O'], '<p>In a disproportionation the same element is both oxidised and reduced. In Cl<sub>2</sub> + 2NaOH, Cl goes 0 to -1 (NaCl) and 0 to +1 (NaClO). In KClO<sub>3</sub> decomposition, Cl is reduced and O is oxidised (different elements).</p>'),
    nat('rx-016', 2, 'balancing', 'In acidic solution MnO<sub>4</sub><sup>-</sup> oxidises Fe<sup>2+</sup> to Fe<sup>3+</sup>, being itself reduced to Mn<sup>2+</sup>. How many Fe<sup>2+</sup> ions are oxidised by one MnO<sub>4</sub><sup>-</sup> ion?', 5, 0, '', '<p>Mn goes +7 to +2: 5 e<sup>-</sup> gained. Each Fe<sup>2+</sup> loses 1 e<sup>-</sup>. So 5 Fe<sup>2+</sup> per MnO<sub>4</sub><sup>-</sup>:</p><p>MnO<sub>4</sub><sup>-</sup> + 5Fe<sup>2+</sup> + 8H<sup>+</sup> &rarr; Mn<sup>2+</sup> + 5Fe<sup>3+</sup> + 4H<sub>2</sub>O. Answer <b>5</b>.</p>', '', () => 7 - 2),
    nat('rx-017', 2, 'n-factor', 'Find the n-factor of K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub> when it changes to Cr<sup>3+</sup> in acidic solution.', 6, 0, '', '<p>Each Cr goes +6 to +3, gaining 3 e<sup>-</sup>. There are two Cr atoms per formula unit: n = 2 &times; 3 = <b>6</b>.</p>', 'Do not forget the two Cr atoms (3 is the common wrong answer).', () => 2 * (6 - 3)),
    mk('rx-018', 2, 'average oxidation number', 'The average oxidation number of sulphur in Na<sub>2</sub>S<sub>4</sub>O<sub>6</sub> is', '+2.5', ['+2', '+3', '+6'], '<p>2(+1) + 4x + 6(-2) = 0 gives 4x = 10, x = +2.5. This is an average: two S atoms are +5 and two are 0 in the structure.</p>'),
    nat('rx-019', 2, 'equivalent weight', 'Find the equivalent weight of oxalic acid H<sub>2</sub>C<sub>2</sub>O<sub>4</sub> (molar mass 90 g mol<sup>-1</sup>) when it is oxidised to CO<sub>2</sub>.', 45, 0, 'g eq<sup>-1</sup>', '<p>Each of the two C atoms goes +3 to +4, so the n-factor is 2. Equivalent weight = 90/2 = <b>45 g</b>.</p>', '', () => 90 / 2),
    nat('rx-020', 2, 'electrochemical series', 'Find the standard cell potential for the reaction Zn + Cu<sup>2+</sup> &rarr; Zn<sup>2+</sup> + Cu. E&deg;(Zn<sup>2+</sup>/Zn) = -0.76 V; E&deg;(Cu<sup>2+</sup>/Cu) = +0.34 V.', 1.1, 0.01, 'V', '<p>E&deg;<sub>cell</sub> = E&deg;(reduction half) - E&deg;(oxidation half) = E&deg;(Cu<sup>2+</sup>/Cu) - E&deg;(Zn<sup>2+</sup>/Zn) = 0.34 - (-0.76) = <b>1.10 V</b>. Positive: the reaction is spontaneous.</p>', 'Do not change the sign of E&deg; when you double the half-reaction.', () => 0.34 + 0.76),
    mk('rx-021', 2, 'electrochemical series', 'Which of these metals does <b>not</b> liberate hydrogen from dilute hydrochloric acid?', 'Cu (E&deg; = +0.34 V)', ['Zn (E&deg; = -0.76 V)', 'Fe (E&deg; = -0.44 V)', 'Mg (E&deg; = -2.37 V)'], '<p>A metal reduces H<sup>+</sup> only if its E&deg; (reduction) is below 0.00 V (hydrogen electrode). Cu is above hydrogen in the series, so it cannot displace H<sub>2</sub> from dilute HCl.</p>'),
    mk('rx-022', 1, 'oxidation number', 'The oxidation number of carbon in HCHO (formaldehyde) is', '0', ['+2', '-2', '+4'], '<p>2(+1) + x + (-2) = 0 gives x = 0.</p>', 'The usual guess +2 comes from thinking of the C=O bond only.'),
    mk('rx-023', 1, 'oxidation number', 'The oxidation number of phosphorus in H<sub>3</sub>PO<sub>3</sub> is', '+3', ['+1', '+5', '-3'], '<p>3(+1) + x + 3(-2) = 0 gives x = +3. (H<sub>3</sub>PO<sub>2</sub> is +1 and H<sub>3</sub>PO<sub>4</sub> is +5.)</p>'),
    mk('rx-024', 2, 'oxidising agents', 'In Cu + 4HNO<sub>3</sub> (conc.) &rarr; Cu(NO<sub>3</sub>)<sub>2</sub> + 2NO<sub>2</sub> + 2H<sub>2</sub>O, nitric acid acts as', 'an oxidising agent and an acid', ['only an oxidising agent', 'only an acid', 'a reducing agent'], '<p>Two of the four HNO<sub>3</sub> are reduced to NO<sub>2</sub> (N: +5 to +4), so they are oxidising agents. The other two supply NO<sub>3</sub><sup>-</sup> for the salt without change in oxidation number: acting as an acid.</p>'),
    nat('rx-025', 2, 'normality', 'Find the normality of 0.020 M KMnO<sub>4</sub> in acidic medium.', 0.1, 0.001, 'N', '<p>Normality = molarity &times; n-factor = 0.020 &times; 5 = <b>0.10 N</b>.</p>', '', () => 0.02 * 5),
    mk('rx-026', 2, 'redox titrations', 'In titrating oxalic acid with KMnO<sub>4</sub> in acid, the end point is shown by', 'a faint permanent pink colour from the first excess drop of KMnO<sub>4</sub>', ['the disappearance of the purple colour', 'a blue colour with starch', 'the appearance of a brown precipitate'], '<p>KMnO<sub>4</sub> is a self-indicator: purple MnO<sub>4</sub><sup>-</sup> turns colourless Mn<sup>2+</sup> until all oxalate is used; the first extra drop then leaves a permanent pale pink. Starch is for iodine titrations.</p>'),
    mk('rx-027', 2, 'comproportionation', 'Which of these is a comproportionation (reverse disproportionation) reaction?', 'IO<sub>3</sub><sup>-</sup> + 5I<sup>-</sup> + 6H<sup>+</sup> &rarr; 3I<sub>2</sub> + 3H<sub>2</sub>O', ['2H<sub>2</sub>O<sub>2</sub> &rarr; 2H<sub>2</sub>O + O<sub>2</sub>', '3Cl<sub>2</sub> + 6OH<sup>-</sup> &rarr; 5Cl<sup>-</sup> + ClO<sub>3</sub><sup>-</sup> + 3H<sub>2</sub>O', 'Zn + 2HCl &rarr; ZnCl<sub>2</sub> + H<sub>2</sub>'], '<p>Comproportionation: the same element in a higher state (I in IO<sub>3</sub><sup>-</sup>, +5) and a lower state (I<sup>-</sup>, -1) both go to one intermediate state (I<sub>2</sub>, 0). The two middle ones are disproportionations.</p>'),
    mk('rx-028', 2, 'oxidising and reducing agents', 'In 2H<sub>2</sub>S + SO<sub>2</sub> &rarr; 3S + 2H<sub>2</sub>O the oxidising agent is', 'SO<sub>2</sub>', ['H<sub>2</sub>S', 'S', 'H<sub>2</sub>O'], '<p>S in SO<sub>2</sub> goes +4 to 0 (reduced): SO<sub>2</sub> is the oxidising agent. S in H<sub>2</sub>S goes -2 to 0 (oxidised): H<sub>2</sub>S is the reducing agent.</p>'),
    mk('rx-029', 1, 'oxidation number', 'The oxidation number of nitrogen in hydrazine N<sub>2</sub>H<sub>4</sub> is', '-2', ['-3', '+2', '-4'], '<p>2x + 4(+1) = 0 gives x = -2. (NH<sub>3</sub> is -3, NH<sub>2</sub>OH is -1.)</p>'),
    mk('rx-030', 2, 'electrochemical series', 'Standard reduction potentials are Cu<sup>2+</sup>/Cu +0.34 V, Zn<sup>2+</sup>/Zn -0.76 V, Mg<sup>2+</sup>/Mg -2.37 V and Ag<sup>+</sup>/Ag +0.80 V. The strongest reducing agent among the metals is', 'Mg', ['Ag', 'Cu', 'Zn'], '<p>The most negative reduction potential means the strongest tendency to lose electrons: Mg (-2.37 V).</p>'),
    mk('rx-031', 1, 'oxidation number rules', 'In potassium superoxide KO<sub>2</sub> the oxidation number of oxygen is', '-1/2', ['-1', '-2', '+1/2'], '<p>K is +1, so the O<sub>2</sub> unit carries -1 in total: each O is -1/2. The ion O<sub>2</sub><sup>-</sup> is called superoxide; peroxide O<sub>2</sub><sup>2-</sup> gives -1 each.</p>', 'Peroxide -1, superoxide -1/2.'),
    mk('rx-032', 2, 'n-factor', 'The n-factor of KMnO<sub>4</sub> in neutral or weakly basic solution (product MnO<sub>2</sub>) is', '3', ['5', '1', '7'], '<p>Mn goes from +7 to +4: three electrons gained, so n = 3 and equivalent weight = M/3 (52.7 for KMnO<sub>4</sub>). In acid n = 5; in strong base (MnO<sub>4</sub><sup>2-</sup>) n = 1.</p>'),

    // ---------- Level 3 ----------
    nat('rx-033', 3, 'n-factor', 'Find the n-factor of ferrous oxalate FeC<sub>2</sub>O<sub>4</sub> when KMnO<sub>4</sub> in acid oxidises it to Fe<sup>3+</sup> and CO<sub>2</sub>.', 3, 0, '', '<p>Fe: +2 to +3 gives 1 e<sup>-</sup>. Two C in C<sub>2</sub>O<sub>4</sub><sup>2-</sup>: +3 to +4 give 2 e<sup>-</sup>. Total n = <b>3</b>.</p>', 'Both the Fe<sup>2+</sup> and the oxalate are oxidised.', () => 1 + 2),
    mk('rx-034', 3, 'oxidation number of peroxides', 'In CrO<sub>5</sub> (blue peroxide with four O in peroxide linkages and one O as oxide), the oxidation number of Cr is', '+6', ['+10', '+5', '+4'], '<p>Four O in two peroxide groups are -1 each (-4), the fifth O is -2. Total for O = -6, so Cr = +6. The formal value +10 from simple counting (5 &times; -2) is impossible for Cr (maximum +6).</p>', 'Whenever the formula gives an impossible state, look for peroxide O-O links.'),
    nat('rx-035', 3, 'oxidation number of peroxides', 'Caro&rsquo;s acid, H<sub>2</sub>SO<sub>5</sub>, has one peroxide linkage. Find the oxidation number of sulphur.', 6, 0, '', '<p>Two O are in the peroxide (-1 each); the other three O are -2. Sum of O = -2 - 6 = -8. With 2 H (+2): 2 + x - 8 = 0, x = <b>+6</b>. (Treating all five O as -2 gives the impossible +8.)</p>', '', () => 8 - 2),
    nat('rx-036', 3, 'redox titrations', '25.0 mL of 0.10 M oxalic acid is titrated in acid with 0.050 M KMnO<sub>4</sub>. Find the volume of KMnO<sub>4</sub> needed.', 20, 0, 'mL', '<p>2MnO<sub>4</sub><sup>-</sup> + 5C<sub>2</sub>O<sub>4</sub><sup>2-</sup> + 16H<sup>+</sup> &rarr; 2Mn<sup>2+</sup> + 10CO<sub>2</sub> + 8H<sub>2</sub>O.</p><p>mmol oxalate = 25.0 &times; 0.10 = 2.50. mmol MnO<sub>4</sub><sup>-</sup> = 2.50 &times; 2/5 = 1.00.</p><p>Volume = 1.00/0.050 = <b>20 mL</b>.</p>', 'Use the 2:5 mole ratio (or equal equivalents).', () => 25 * 0.1 * 2 / 5 / 0.05),
    nat('rx-037', 3, 'equivalent weight and mass', 'What mass of K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub> (294 g mol<sup>-1</sup>) is needed to oxidise 0.100 mol of Fe<sup>2+</sup> to Fe<sup>3+</sup> in acid?', 4.9, 0.05, 'g', '<p>Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> + 6Fe<sup>2+</sup> + 14H<sup>+</sup> &rarr; 2Cr<sup>3+</sup> + 6Fe<sup>3+</sup> + 7H<sub>2</sub>O.</p><p>Moles of dichromate = 0.100/6 = 0.01667. Mass = 0.01667 &times; 294 = <b>4.9 g</b>.</p>', '', () => 0.1 / 6 * 294),
    nat('rx-038', 3, 'n-factor and moles', 'How many moles of KMnO<sub>4</sub> (acidic) are needed to oxidise 1 mole of FeC<sub>2</sub>O<sub>4</sub> completely?', 0.6, 0.01, 'mol', '<p>FeC<sub>2</sub>O<sub>4</sub> has n = 3 (1 from Fe, 2 from oxalate) and gives 3 equivalents. KMnO<sub>4</sub> has n = 5.</p><p>Moles of KMnO<sub>4</sub> = 3/5 = <b>0.6</b>.</p>', 'Equivalents of oxidant = equivalents of reductant.', () => 3 / 5),
    nat('rx-039', 3, 'balancing in base', 'In basic solution, 2MnO<sub>4</sub><sup>-</sup> + I<sup>-</sup> + H<sub>2</sub>O &rarr; 2MnO<sub>2</sub> + IO<sub>3</sub><sup>-</sup> + 2OH<sup>-</sup>. How many electrons are transferred in this balanced equation?', 6, 0, '', '<p>Each Mn: +7 to +4, 3 e<sup>-</sup> gained; two Mn gain 6. I: -1 to +5, 6 e<sup>-</sup> lost. So <b>6</b> electrons are transferred.</p>', '', () => 2 * 3),
    nat('rx-040', 3, 'equivalent weight', 'Find the equivalent weight of Cl<sub>2</sub> (M = 71) in its reaction with cold dilute NaOH: Cl<sub>2</sub> + 2OH<sup>-</sup> &rarr; Cl<sup>-</sup> + ClO<sup>-</sup> + H<sub>2</sub>O.', 71, 0, 'g eq<sup>-1</sup>', '<p>One Cl<sub>2</sub> molecule gives one Cl<sup>-</sup> (gains 1 e<sup>-</sup>) and one ClO<sup>-</sup> (loses 1 e<sup>-</sup>). The n-factor of a disproportionating species counts only the electrons gained (or lost), here 1. Equivalent weight = 71/1 = <b>71</b>.</p>', 'Do not add the electrons gained and lost: n-factor is 1, not 2.', () => 71 / 1),
    mk('rx-041', 3, 'disproportionation', 'Which of these species <b>cannot</b> undergo disproportionation?', 'ClO<sub>4</sub><sup>-</sup>', ['ClO<sup>-</sup>', 'ClO<sub>3</sub><sup>-</sup>', 'ClO<sub>2</sub><sup>-</sup>'], '<p>Disproportionation needs the element in an intermediate state, able both to rise and to fall. Cl in ClO<sub>4</sub><sup>-</sup> is +7, its highest state, so it can only be reduced.</p>'),
    nat('rx-042', 3, 'redox titrations', 'A sample of hydrogen peroxide is labelled &ldquo;20 volume&rdquo;, meaning 1 mL gives 20 mL O<sub>2</sub> at STP on decomposition (2H<sub>2</sub>O<sub>2</sub> &rarr; 2H<sub>2</sub>O + O<sub>2</sub>). Find its molarity.', 1.79, 0.02, 'M', '<p>1 L gives 20 L O<sub>2</sub> = 20/22.4 = 0.893 mol O<sub>2</sub>.</p><p>2 mol H<sub>2</sub>O<sub>2</sub> per mol O<sub>2</sub>: 1.786 mol per litre. Molarity = <b>1.79 M</b> (about 6.1 % w/v).</p>', 'Two moles of H<sub>2</sub>O<sub>2</sub> give one mole of O<sub>2</sub>.', () => 20 / 22.4 * 2),
    mk('rx-043', 3, 'electrochemical series', 'E&deg; values: Zn<sup>2+</sup>/Zn -0.76 V, Fe<sup>2+</sup>/Fe -0.44 V, Cu<sup>2+</sup>/Cu +0.34 V, Ag<sup>+</sup>/Ag +0.80 V. Which reaction is spontaneous under standard conditions?', 'Zn + Fe<sup>2+</sup> &rarr; Zn<sup>2+</sup> + Fe', ['Cu + Zn<sup>2+</sup> &rarr; Cu<sup>2+</sup> + Zn', 'Ag + Cu<sup>2+</sup> &rarr; Ag<sup>+</sup> + Cu', 'Cu + Fe<sup>2+</sup> &rarr; Cu<sup>2+</sup> + Fe'], '<p>A reaction is spontaneous if E&deg;<sub>cell</sub> &gt; 0. Zn + Fe<sup>2+</sup>: -0.44 - (-0.76) = +0.32 V (yes). Cu + Zn<sup>2+</sup>: -0.76 - 0.34 = -1.10 V. Ag + Cu<sup>2+</sup>: 0.34 - 0.80 = -0.46 V. Cu + Fe<sup>2+</sup>: -0.44 - 0.34 = -0.78 V. Only the first is positive.</p>'),
    nat('rx-044', 3, 'electrochemical series', 'Fe<sup>3+</sup> (E&deg;(Fe<sup>3+</sup>/Fe<sup>2+</sup>) = +0.77 V) can oxidise I<sup>-</sup> to I<sub>2</sub> (E&deg;(I<sub>2</sub>/I<sup>-</sup>) = +0.54 V). Find E&deg;<sub>cell</sub>.', 0.23, 0.005, 'V', '<p>E&deg;<sub>cell</sub> = 0.77 - 0.54 = <b>+0.23 V</b>. The positive value shows the reaction 2Fe<sup>3+</sup> + 2I<sup>-</sup> &rarr; 2Fe<sup>2+</sup> + I<sub>2</sub> is spontaneous.</p>', '', () => 0.77 - 0.54),
    nat('rx-045', 3, 'electrochemical series', 'Find &Delta;G&deg; (in kJ) for Zn + Cu<sup>2+</sup> &rarr; Zn<sup>2+</sup> + Cu, given E&deg;<sub>cell</sub> = 1.10 V. (F = 96500 C mol<sup>-1</sup>)', -212.3, 0.5, 'kJ mol<sup>-1</sup>', '<p>&Delta;G&deg; = -nFE&deg; with n = 2: -2 &times; 96500 &times; 1.10 = -212 300 J = <b>-212.3 kJ</b>. Negative, so spontaneous.</p>', '', () => -2 * 96500 * 1.1 / 1000),
    nat('rx-046', 3, 'equivalent weight and mass', 'What mass of Mohr&rsquo;s salt, FeSO<sub>4</sub>&middot;(NH<sub>4</sub>)<sub>2</sub>SO<sub>4</sub>&middot;6H<sub>2</sub>O (M = 392), is needed to prepare 250 mL of 0.100 N solution for use as a reducing agent?', 9.8, 0.05, 'g', '<p>Fe<sup>2+</sup> loses 1 e<sup>-</sup>, so n = 1 and equivalent weight = 392.</p><p>Equivalents = 0.100 &times; 0.250 = 0.0250. Mass = 0.0250 &times; 392 = <b>9.8 g</b>.</p>', '', () => 0.1 * 0.25 * 392),
    nat('rx-047', 4, 'balancing in base', 'Chlorine reacts with hot concentrated NaOH: Cl<sub>2</sub> + OH<sup>-</sup> &rarr; Cl<sup>-</sup> + ClO<sub>3</sub><sup>-</sup> + H<sub>2</sub>O. In the balanced equation with smallest whole numbers, find the sum of all coefficients.', 18, 0, '', '<p>Cl goes 0 to -1 (gains 1) and 0 to +5 (loses 5). For equal electrons: 5 Cl<sup>-</sup> per 1 ClO<sub>3</sub><sup>-</sup>, so 6 Cl atoms = 3 Cl<sub>2</sub>.</p><p>3Cl<sub>2</sub> + 6OH<sup>-</sup> &rarr; 5Cl<sup>-</sup> + ClO<sub>3</sub><sup>-</sup> + 3H<sub>2</sub>O. Charge: -6 = -6. Sum = 3 + 6 + 5 + 1 + 3 = <b>18</b>.</p>', '', () => 3 + 6 + 5 + 1 + 3),
    nat('rx-048', 3, 'balancing in acid', 'Acidified KMnO<sub>4</sub> oxidises H<sub>2</sub>O<sub>2</sub> to O<sub>2</sub>: MnO<sub>4</sub><sup>-</sup> + H<sub>2</sub>O<sub>2</sub> + H<sup>+</sup> &rarr; Mn<sup>2+</sup> + O<sub>2</sub> + H<sub>2</sub>O. Find the sum of the coefficients in the balanced equation (smallest whole numbers).', 28, 0, '', '<p>Mn gains 5 e<sup>-</sup>; each H<sub>2</sub>O<sub>2</sub> loses 2 e<sup>-</sup> (O: -1 to 0 for two atoms). LCM 10: 2 MnO<sub>4</sub><sup>-</sup> and 5 H<sub>2</sub>O<sub>2</sub>.</p><p>2MnO<sub>4</sub><sup>-</sup> + 5H<sub>2</sub>O<sub>2</sub> + 6H<sup>+</sup> &rarr; 2Mn<sup>2+</sup> + 5O<sub>2</sub> + 8H<sub>2</sub>O (charge +4 both sides).</p><p>Sum = 2 + 5 + 6 + 2 + 5 + 8 = <b>28</b>.</p>', '', () => 2 + 5 + 6 + 2 + 5 + 8),
    nat('rx-049', 4, 'balancing in base', 'In basic solution Cr(OH)<sub>3</sub> is oxidised by ClO<sub>3</sub><sup>-</sup>: Cr(OH)<sub>3</sub> + ClO<sub>3</sub><sup>-</sup> + OH<sup>-</sup> &rarr; CrO<sub>4</sub><sup>2-</sup> + Cl<sup>-</sup> + H<sub>2</sub>O. Find the coefficient of OH<sup>-</sup> in the balanced equation.', 4, 0, '', '<p>Cr: +3 to +6 (loses 3); Cl: +5 to -1 (gains 6). So 2 Cr(OH)<sub>3</sub> per ClO<sub>3</sub><sup>-</sup>.</p><p>Charge: left -1 + (-x) must equal right -4 - 1 = -5, so x = 4.</p><p>2Cr(OH)<sub>3</sub> + ClO<sub>3</sub><sup>-</sup> + 4OH<sup>-</sup> &rarr; 2CrO<sub>4</sub><sup>2-</sup> + Cl<sup>-</sup> + 5H<sub>2</sub>O. Coefficient <b>4</b>.</p>', 'Balance charge last, with OH<sup>-</sup> in base.', () => 4),
    nat('rx-050', 3, 'mixed with ionic equilibrium', 'A 1.0 L solution holds 0.30 M H<sup>+</sup> (from H<sub>2</sub>SO<sub>4</sub>) plus Fe<sup>2+</sup>. Then 0.020 mol KMnO<sub>4</sub> is added and completely oxidises Fe<sup>2+</sup>: MnO<sub>4</sub><sup>-</sup> + 5Fe<sup>2+</sup> + 8H<sup>+</sup> &rarr; Mn<sup>2+</sup> + 5Fe<sup>3+</sup> + 4H<sub>2</sub>O. Find the pH afterwards (no volume change).', 0.85, 0.01, '', '<p>H<sup>+</sup> used = 8 &times; 0.020 = 0.16 mol. Left = 0.30 - 0.16 = 0.14 M.</p><p>pH = -log 0.14 = <b>0.85</b>.</p>', 'Each MnO<sub>4</sub><sup>-</sup> consumes 8 H<sup>+</sup>.', () => -Math.log10(0.3 - 8 * 0.02)),
    mk('rx-051', 3, 'disproportionation', 'Which of the following statements is <b>not</b> correct?', 'NH<sub>4</sub>NO<sub>2</sub> &rarr; N<sub>2</sub> + 2H<sub>2</sub>O is a disproportionation reaction', ['2NO<sub>2</sub> + 2OH<sup>-</sup> &rarr; NO<sub>2</sub><sup>-</sup> + NO<sub>3</sub><sup>-</sup> + H<sub>2</sub>O is a disproportionation reaction', 'NH<sub>4</sub>NO<sub>2</sub> &rarr; N<sub>2</sub> + 2H<sub>2</sub>O is a comproportionation reaction', 'In 2Cu<sup>+</sup> &rarr; Cu<sup>2+</sup> + Cu the same species is oxidised and reduced'], '<p>In NH<sub>4</sub>NO<sub>2</sub> nitrogen is -3 (in NH<sub>4</sub><sup>+</sup>) and +3 (in NO<sub>2</sub><sup>-</sup>); both become 0 in N<sub>2</sub>. Two different oxidation states come together: that is comproportionation, so calling it disproportionation is the wrong statement. NO<sub>2</sub> (+4) giving +3 and +5 and Cu<sup>+</sup> (+1) giving +2 and 0 are genuine disproportionations.</p>', 'In &ldquo;which is NOT correct&rdquo; items, check each option; here the wrong one is the first.'),
    asr('rx-052', 2, 'oxidising and reducing agents', 'Hydrogen peroxide can act as both an oxidising and a reducing agent.', 'Oxygen in H<sub>2</sub>O<sub>2</sub> is in the -1 state, between 0 (O<sub>2</sub>) and -2 (H<sub>2</sub>O).', 0, '<p>Both are true and R explains A. O at -1 can be reduced to -2 (oxidising agent, e.g. H<sub>2</sub>O<sub>2</sub> + 2Fe<sup>2+</sup> + 2H<sup>+</sup> &rarr; 2Fe<sup>3+</sup> + 2H<sub>2</sub>O) or oxidised to 0 (reducing agent, e.g. with MnO<sub>4</sub><sup>-</sup> giving O<sub>2</sub>).</p>'),
    asr('rx-053', 2, 'oxidising and reducing agents', 'KMnO<sub>4</sub> cannot act as a reducing agent (with respect to manganese).', 'Mn in KMnO<sub>4</sub> is already in its highest oxidation state, +7.', 0, '<p>Mn has seven valence electrons (3d<sup>5</sup>4s<sup>2</sup>) and +7 is its maximum. It can only be reduced, never oxidised further, so KMnO<sub>4</sub> is always an oxidising agent. Both true; R is the reason.</p>'),
    asr('rx-054', 3, 'oxidation number rules', 'The oxidation number of oxygen in KO<sub>2</sub> is -1.', 'KO<sub>2</sub> is a superoxide containing the O<sub>2</sub><sup>-</sup> ion.', 3, '<p>A is false: with the ion O<sub>2</sub><sup>-</sup> (two atoms, total charge -1) each O is -1/2. R is a true statement.</p>', 'Peroxide gives -1; superoxide -1/2.'),
    asr('rx-055', 3, 'oxidation number of peroxides', 'The oxidation number of chromium in CrO<sub>5</sub> is +6.', 'CrO<sub>5</sub> contains one peroxide linkage.', 2, '<p>A is true (+6, as worked earlier). R is false: CrO<sub>5</sub> has two peroxide linkages (four O at -1) and one O at -2: 4(-1) + (-2) + 6 = 0. With one peroxide the total would not balance.</p>'),
    asr('rx-056', 3, 'oxidation number rules', 'The oxidation number of hydrogen in NaH is -1.', 'Hydrogen is the lightest element.', 1, '<p>A is true: H is more electronegative than Na, so H is -1. R is a true fact but has nothing to do with the oxidation state: it is electronegativity that decides.</p>'),
    asr('rx-057', 2, 'redox titrations', 'No separate indicator is needed in the titration of oxalic acid with KMnO<sub>4</sub> in acid.', 'KMnO<sub>4</sub> acts as a self-indicator.', 0, '<p>Both statements are true and R explains A: the purple KMnO<sub>4</sub> is decolourised until the oxalate is finished; one drop in excess gives a permanent pink.</p>'),
    asr('rx-058', 3, 'redox titrations', 'KMnO<sub>4</sub> titrations are acidified with dilute HCl.', 'Dilute H<sub>2</sub>SO<sub>4</sub> is not oxidised by KMnO<sub>4</sub>.', 3, '<p>A is false: HCl is not used because KMnO<sub>4</sub> would also oxidise Cl<sup>-</sup> to Cl<sub>2</sub> and give too high a titre. Dilute H<sub>2</sub>SO<sub>4</sub> is used instead. R is true.</p>'),
    asr('rx-059', 4, 'electrochemical series', 'Among the alkali metals, lithium has the most negative standard reduction potential.', 'Lithium has the lowest ionisation enthalpy of the alkali metals.', 2, '<p>A is true (-3.05 V). R is false: Li has the <i>highest</i> ionisation enthalpy of the group. Its large negative E&deg; comes from the very high hydration enthalpy of the small Li<sup>+</sup> ion.</p>', 'E&deg; includes hydration, not just ionisation enthalpy.'),
    stm('rx-060', 2, 'oxidation number', 'The oxidation number of chromium in CrO<sub>5</sub> is +6.', 'The oxidation number of chromium in K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub> is +6.', 0, '<p>I: four O are -1 (two peroxo groups), one O is -2: Cr = +6. II: 2(+1) + 2x - 14 = 0, x = +6. Both correct.</p>'),
    stm('rx-061', 4, 'oxidation number structures', 'In the thiosulfate ion S<sub>2</sub>O<sub>3</sub><sup>2-</sup> both sulphur atoms have the same oxidation number, +2.', 'In S<sub>2</sub>O<sub>3</sub><sup>2-</sup> the central S is +6 and the terminal S is -2 (average +2).', 2, '<p>Thiosulfate is an SO<sub>4</sub><sup>2-</sup> ion with one O replaced by S. The central S, bonded to three O and one S, is +6; the terminal S, bonded only to S, is -2. The average is +2, but the atoms differ. I is incorrect (+2 is only an average); II is correct.</p>', 'Average oxidation number is not always the real one.'),
    stm('rx-062', 2, 'disproportionation', 'In the reaction of Cl<sub>2</sub> with cold dilute NaOH, chlorine is both oxidised and reduced.', 'In acid solution Cl<sup>-</sup> and ClO<sup>-</sup> react to give Cl<sub>2</sub>, a comproportionation.', 0, '<p>I: Cl goes 0 to -1 and 0 to +1. II: Cl<sup>-</sup> + ClO<sup>-</sup> + 2H<sup>+</sup> &rarr; Cl<sub>2</sub> + H<sub>2</sub>O: -1 and +1 meet at 0. Both correct.</p>'),
    stm('rx-063', 3, 'equivalent weight', 'The equivalent weight of KMnO<sub>4</sub> is the same in acidic, neutral and strongly basic solutions.', 'The n-factor of KMnO<sub>4</sub> depends on the medium (5, 3 or 1).', 2, '<p>I is incorrect: the equivalent weight is M/n, so it is 31.6 in acid, 52.7 in neutral and 158 in strong base. II is correct.</p>'),
    stm('rx-064', 2, 'oxidation number rules', 'The oxidation number of oxygen is -1 in H<sub>2</sub>O<sub>2</sub> and +2 in OF<sub>2</sub>.', 'The oxidation number of oxygen in KO<sub>2</sub> is -1.', 1, '<p>I is correct: peroxide -1; in OF<sub>2</sub> fluorine (more electronegative) is -1, leaving O at +2. II is incorrect: KO<sub>2</sub> is a superoxide with O at -1/2.</p>'),
    stm('rx-065', 3, 'oxidising and reducing agents', 'SO<sub>2</sub> can act only as a reducing agent.', 'Sulphur in SO<sub>2</sub> is in the intermediate +4 state, so SO<sub>2</sub> can act as a reducing agent or as an oxidising agent.', 2, '<p>S can range from -2 to +6. At +4 it can rise to +6 (reducing: SO<sub>2</sub> decolourises acidified KMnO<sub>4</sub>) or fall to 0 (oxidising: with H<sub>2</sub>S). I is incorrect, II is correct.</p>'),
    stm('rx-066', 4, 'oxidation number', 'The oxidation number of iron in K<sub>4</sub>[Fe(CN)<sub>6</sub>] is +2.', 'The oxidation number of nickel in Ni(CO)<sub>4</sub> is +4.', 1, '<p>I: 4(+1) + x + 6(-1) = 0, x = +2. Correct. II: CO is a neutral ligand, so Ni = 0. Incorrect.</p>', 'Neutral ligands (CO, H<sub>2</sub>O, NH<sub>3</sub>) add nothing.'),
    stm('rx-067', 4, 'oxidation number', 'The oxidation number of sulphur in H<sub>2</sub>S<sub>2</sub>O<sub>8</sub> (peroxodisulfuric acid) is +7.', 'In Fe<sub>3</sub>O<sub>4</sub> every iron atom is in the +8/3 state.', 3, '<p>I: H<sub>2</sub>S<sub>2</sub>O<sub>8</sub> has one O-O link, so six O are -2 and two O are -1: 2 + 2x - 12 - 2 = 0 gives x = +6 (not +7, which is the naive value). II: Fe<sub>3</sub>O<sub>4</sub> = FeO&middot;Fe<sub>2</sub>O<sub>3</sub> has one Fe<sup>2+</sup> and two Fe<sup>3+</sup>; +8/3 is only an average. Both incorrect.</p>'),
    { id: 'rx-068', type: 'mcq', level: 4, format: 'statements', exams: EX[4], sub: 'mixed counting', q: '<p>How many of the following are disproportionation reactions?</p><p>(a) 2H<sub>2</sub>O<sub>2</sub> &rarr; 2H<sub>2</sub>O + O<sub>2</sub> &nbsp; (b) 2NO<sub>2</sub> + 2OH<sup>-</sup> &rarr; NO<sub>2</sub><sup>-</sup> + NO<sub>3</sub><sup>-</sup> + H<sub>2</sub>O &nbsp; (c) NH<sub>4</sub>NO<sub>2</sub> &rarr; N<sub>2</sub> + 2H<sub>2</sub>O &nbsp; (d) 3MnO<sub>4</sub><sup>2-</sup> + 4H<sup>+</sup> &rarr; 2MnO<sub>4</sub><sup>-</sup> + MnO<sub>2</sub> + 2H<sub>2</sub>O &nbsp; (e) PCl<sub>5</sub> &rarr; PCl<sub>3</sub> + Cl<sub>2</sub></p>', options: ['1', '2', '3', '4'], answer: 2, sol: '<p>(a) O: -1 gives -2 and 0: yes. (b) N: +4 gives +3 and +5: yes. (c) N: -3 and +3 meet at 0: comproportionation, no. (d) Mn: +6 gives +7 and +4: yes. (e) P is reduced (+5 to +3) and Cl is oxidised (-1 to 0): different elements, so it is intramolecular redox, not disproportionation. Three are disproportionations.</p>', trap: 'Disproportionation needs the same element in one species to be both oxidised and reduced.' },
    msq('rx-069', 2, 'oxidation number', 'In which of the following species does sulphur have oxidation number +6?', ['H<sub>2</sub>SO<sub>4</sub>', 'H<sub>2</sub>S<sub>2</sub>O<sub>8</sub>', 'Na<sub>2</sub>S<sub>2</sub>O<sub>3</sub> (average)', 'SO<sub>3</sub>', 'H<sub>2</sub>SO<sub>5</sub>'], [0, 1, 3, 4], '<p>H<sub>2</sub>SO<sub>4</sub>: +6. H<sub>2</sub>S<sub>2</sub>O<sub>8</sub> and H<sub>2</sub>SO<sub>5</sub> contain peroxide O (-1) which compensates: still +6. SO<sub>3</sub>: +6. Na<sub>2</sub>S<sub>2</sub>O<sub>3</sub> averages +2.</p>'),
    msq('rx-070', 3, 'disproportionation', 'Which of these are disproportionation reactions?', ['2Cu<sup>+</sup> &rarr; Cu<sup>2+</sup> + Cu', 'P<sub>4</sub> + 3NaOH + 3H<sub>2</sub>O &rarr; PH<sub>3</sub> + 3NaH<sub>2</sub>PO<sub>2</sub>', '2KClO<sub>3</sub> &rarr; 2KCl + 3O<sub>2</sub>', 'NH<sub>4</sub>NO<sub>3</sub> &rarr; N<sub>2</sub>O + 2H<sub>2</sub>O'], [0, 1], '<p>(A) Cu: +1 to +2 and 0. (B) P: 0 to -3 (PH<sub>3</sub>) and +1 (H<sub>2</sub>PO<sub>2</sub><sup>-</sup>). (C) Cl is reduced, O oxidised: intramolecular redox. (D) N is -3 and +5, both go to +1: comproportionation.</p>'),
    msq('rx-071', 3, 'oxidising and reducing agents', 'Which of the following can act as both oxidising and reducing agents?', ['H<sub>2</sub>O<sub>2</sub>', 'SO<sub>2</sub>', 'HNO<sub>2</sub>', 'H<sub>2</sub>S', 'KMnO<sub>4</sub>'], [0, 1, 2], '<p>An element in an intermediate state can go either way: O in H<sub>2</sub>O<sub>2</sub> (-1), S in SO<sub>2</sub> (+4), N in HNO<sub>2</sub> (+3). S in H<sub>2</sub>S is -2 (lowest) and Mn in KMnO<sub>4</sub> is +7 (highest): each can go one way only.</p>'),
    msq('rx-072', 2, 'oxidation number', 'In which species does manganese have oxidation number +7?', ['KMnO<sub>4</sub>', 'Mn<sub>2</sub>O<sub>7</sub>', 'K<sub>2</sub>MnO<sub>4</sub>', 'MnO<sub>2</sub>'], [0, 1], '<p>KMnO<sub>4</sub>: +7. Mn<sub>2</sub>O<sub>7</sub>: 2x = 14, x = +7. K<sub>2</sub>MnO<sub>4</sub>: +6. MnO<sub>2</sub>: +4.</p>'),
    msq('rx-073', 2, 'oxidation number rules', 'In which of the following does oxygen have an oxidation number of -1?', ['Na<sub>2</sub>O<sub>2</sub>', 'BaO<sub>2</sub>', 'KO<sub>2</sub>', 'H<sub>2</sub>O<sub>2</sub>'], [0, 1, 3], '<p>Peroxides contain O<sub>2</sub><sup>2-</sup>: Na<sub>2</sub>O<sub>2</sub>, BaO<sub>2</sub> and H<sub>2</sub>O<sub>2</sub> all have O at -1. KO<sub>2</sub> is a superoxide: -1/2.</p>'),
    msq('rx-074', 2, 'equivalent weight', 'Choose the correct equivalent weights (M = molar mass).', ['KMnO<sub>4</sub> in acid: M/5', 'K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub> in acid: M/6', 'H<sub>2</sub>C<sub>2</sub>O<sub>4</sub> oxidised to CO<sub>2</sub>: M/2', 'FeSO<sub>4</sub> oxidised to Fe<sup>3+</sup>: M/2'], [0, 1, 2], '<p>n-factors: Mn +7 to +2 is 5; two Cr, 3 each, is 6; two C, 1 each, is 2; Fe<sup>2+</sup> to Fe<sup>3+</sup> is 1 (equivalent weight = M, not M/2).</p>'),
    msq('rx-075', 2, 'electrochemical series', 'Which statements about the electrochemical series are correct?', ['Li is the strongest reducing agent among the metals listed in the series', 'F<sub>2</sub> is the strongest oxidising agent', 'Copper does not liberate hydrogen from dilute HCl', 'Silver displaces copper from copper sulfate solution'], [0, 1, 2], '<p>Li (-3.05 V) is the most easily oxidised; F<sub>2</sub> (+2.87 V) the most easily reduced; Cu (+0.34 V) lies above hydrogen so it cannot give H<sub>2</sub>. Silver (+0.80 V) is higher than copper, so Cu displaces Ag, not the other way round.</p>'),
    mat('rx-076', 3, 'oxidation number', 'm1', 'Match the species with the oxidation number of the stated atom.', 'A-q, B-p, C-r, D-s', ['A-p, B-q, C-r, D-s', 'A-q, B-r, C-p, D-s', 'A-r, B-p, C-q, D-s'], '<p>A. S<sub>4</sub>O<sub>6</sub><sup>2-</sup>: 4x - 12 = -2, x = +5/2. B. CrO<sub>5</sub>: +6. C. Fe<sub>3</sub>O<sub>4</sub>: +8/3. D. KO<sub>2</sub>: -1/2.</p>'),
    mat('rx-077', 3, 'n-factor', 'm2', 'Match each oxidant or reductant with its n-factor.', 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-r, C-q, D-s', 'A-p, B-q, C-s, D-r'], '<p>A. Mn +7 to +2: 5. B. two Cr, +6 to +3: 6. C. Mn +7 to +4: 3. D. Fe<sup>2+</sup> to Fe<sup>3+</sup>: 1.</p>'),
    mat('rx-078', 3, 'types of redox reaction', 'm3', 'Match the type with an example.', 'A-q, B-r, C-p, D-s', ['A-p, B-r, C-q, D-s', 'A-q, B-p, C-r, D-s', 'A-r, B-q, C-p, D-s'], '<p>A. 2H<sub>2</sub>O<sub>2</sub> &rarr; 2H<sub>2</sub>O + O<sub>2</sub>: O (-1) goes to -2 and 0 (disproportionation). B. IO<sub>3</sub><sup>-</sup> + I<sup>-</sup> &rarr; I<sub>2</sub>: two states to one (comproportionation). C. Zn + CuSO<sub>4</sub>: a more active metal displaces a less active one. D. 2KClO<sub>3</sub> &rarr; 2KCl + 3O<sub>2</sub>: Cl is reduced and O oxidised inside the same compound.</p>'),
    mat('rx-079', 3, 'redox titrations', 'm4', 'Match each titration with its end-point fact.', 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-r, C-q, D-s', 'A-p, B-q, C-s, D-r'], '<p>A. Permanganate is its own indicator. B. Iodine needs starch (blue complex) added near the end point. C. Dichromate is not self-indicating; diphenylamine is used. D. In HCl, KMnO<sub>4</sub> also oxidises Cl<sup>-</sup> to Cl<sub>2</sub>, using extra permanganate: high result.</p>'),

    // ---------- Level 4 ----------
    nat('rx-080', 5, 'n-factor', 'Find the n-factor of As<sub>2</sub>S<sub>3</sub> when it is oxidised to AsO<sub>4</sub><sup>3-</sup> and SO<sub>4</sub><sup>2-</sup>.', 28, 0, '', '<p>As: +3 to +5 gives 2 e<sup>-</sup> each &times; 2 As = 4. S: -2 to +6 gives 8 e<sup>-</sup> each &times; 3 S = 24.</p><p>n = 4 + 24 = <b>28</b>.</p>', 'Count both elements and all the atoms.', () => 2 * 2 + 3 * 8),
    nat('rx-081', 4, 'n-factor', 'Find the n-factor of Cu<sub>2</sub>S when it is oxidised to Cu<sup>2+</sup> and SO<sub>2</sub>.', 8, 0, '', '<p>Cu: +1 to +2, 1 e<sup>-</sup> each &times; 2 = 2. S: -2 to +4 = 6 e<sup>-</sup>.</p><p>n = 2 + 6 = <b>8</b>.</p>', '', () => 2 * 1 + 6),
    nat('rx-082', 5, 'oxidation number structures', 'The structure of the tetrathionate ion S<sub>4</sub>O<sub>6</sub><sup>2-</sup> is O<sub>3</sub>S-S-S-SO<sub>3</sub> (two end S, each bonded to three O, and two middle S joined to each other). How many of its four sulphur atoms have oxidation number zero?', 2, 0, '', '<p>The end S atoms (bonded to three O and one S) are +5 each. The two middle S atoms are bonded only to S, so each is 0. Check: 5 + 5 + 0 + 0 = 10 = 4 &times; 2.5, so the average is +2.5.</p><p>Answer <b>2</b>.</p>', 'The average +2.5 is not the real state of any S atom.', () => 2),
    nat('rx-083', 4, 'equivalent weight', 'Find the equivalent weight of Cl<sub>2</sub> (M = 71) in its reaction with hot concentrated NaOH, 3Cl<sub>2</sub> + 6OH<sup>-</sup> &rarr; 5Cl<sup>-</sup> + ClO<sub>3</sub><sup>-</sup> + 3H<sub>2</sub>O.', 42.6, 0.1, 'g eq<sup>-1</sup>', '<p>Electrons lost in the reaction = 5 (one Cl: 0 to +5), for 3 mol Cl<sub>2</sub>. So the n-factor of Cl<sub>2</sub> = 5/3.</p><p>Equivalent weight = 71/(5/3) = <b>42.6</b>.</p>', 'This is a disproportionation: use electrons lost per mole of the whole reactant, 5/3.', () => 71 / (5 / 3)),
    nat('rx-084', 4, 'redox titrations', '0.719 g of FeC<sub>2</sub>O<sub>4</sub> (M = 143.9; 5.00 mmol) is dissolved in dilute H<sub>2</sub>SO<sub>4</sub>. What volume of 0.0200 M KMnO<sub>4</sub> oxidises it completely?', 150, 0, 'mL', '<p>n-factor of FeC<sub>2</sub>O<sub>4</sub> = 3, so meq = 5.00 &times; 3 = 15.0 meq. N of KMnO<sub>4</sub> = 0.0200 &times; 5 = 0.100 N.</p><p>V = 15.0/0.100 = <b>150 mL</b>.</p>', 'Use n = 3 for ferrous oxalate and n = 5 for permanganate.', () => 5 * 3 / (0.02 * 5)),
    nat('rx-085', 4, 'iodometry', '0.147 g of K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub> (M = 294) is treated with excess KI in acid (Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> + 6I<sup>-</sup> + 14H<sup>+</sup> &rarr; 2Cr<sup>3+</sup> + 3I<sub>2</sub> + 7H<sub>2</sub>O). The iodine is titrated with 0.100 M Na<sub>2</sub>S<sub>2</sub>O<sub>3</sub>. Find the volume needed in mL.', 30, 0, 'mL', '<p>mmol dichromate = 147/294 = 0.500. Each gives 3 I<sub>2</sub> = 1.50 mmol I<sub>2</sub>.</p><p>Each I<sub>2</sub> needs 2 S<sub>2</sub>O<sub>3</sub><sup>2-</sup>: 3.00 mmol. Volume = 3.00/0.100 = <b>30 mL</b>. (Check by equivalents: 0.5 &times; 6 = 3 meq.)</p>', 'One dichromate corresponds to six thiosulfate.', () => 0.5 * 3 * 2 / 0.1),
    nat('rx-086', 4, 'electrochemical series (mixed with thermodynamics)', 'For Zn + Cu<sup>2+</sup> &rarr; Zn<sup>2+</sup> + Cu, E&deg;<sub>cell</sub> = 1.10 V at 298 K. Find log<sub>10</sub> K for the reaction using log K = nE&deg;/0.0592.', 37.2, 0.1, '', '<p>n = 2: log K = 2 &times; 1.10/0.0592 = <b>37.2</b>, so K is about 10<sup>37</sup>: the reaction goes essentially to completion.</p>', '', () => 2 * 1.1 / 0.0592),
    mk('rx-087', 4, 'redox titrations', 'A student acidifies a solution of Fe<sup>2+</sup> with dilute HCl before titrating with KMnO<sub>4</sub>. The result is too high because', 'KMnO<sub>4</sub> also oxidises Cl<sup>-</sup> to Cl<sub>2</sub>, using extra titrant', ['HCl reduces Fe<sup>3+</sup> back to Fe<sup>2+</sup>', 'HCl turns the end point colour into brown', 'Cl<sup>-</sup> catalyses the oxidation of Fe<sup>2+</sup> by air'], '<p>E&deg;(MnO<sub>4</sub><sup>-</sup>/Mn<sup>2+</sup>) = +1.51 V is above E&deg;(Cl<sub>2</sub>/Cl<sup>-</sup>) = +1.36 V, so permanganate can oxidise chloride. The extra KMnO<sub>4</sub> consumed is counted as if it had reacted with Fe<sup>2+</sup>. Dilute H<sub>2</sub>SO<sub>4</sub> is used because sulphate is not oxidised.</p>'),
    mk('rx-088', 4, 'electrochemical series', 'The reactions A + B<sup>2+</sup> &rarr; A<sup>2+</sup> + B and C + B<sup>2+</sup> &rarr; no reaction, and C<sup>2+</sup> + A &rarr; A<sup>2+</sup> + C are observed. The order of reducing power (strongest first) is', 'A &gt; B &gt; C', ['A &gt; C &gt; B', 'B &gt; A &gt; C', 'C &gt; B &gt; A'], '<p>A displaces B<sup>2+</sup>, so A is a stronger reductant than B. C does not displace B<sup>2+</sup>, so C is weaker than B. A also displaces C<sup>2+</sup> (A stronger than C). Hence A &gt; B &gt; C.</p>', 'No reaction means the metal is a weaker reductant than the one in the ion.'),
    mk('rx-089', 4, 'balancing', 'In the balanced equation of Zn with dilute nitrate in basic solution forming ammonia, 4Zn + NO<sub>3</sub><sup>-</sup> + 7OH<sup>-</sup> + 6H<sub>2</sub>O &rarr; 4[Zn(OH)<sub>4</sub>]<sup>2-</sup> + NH<sub>3</sub>, the number of electrons transferred per nitrate ion is', '8', ['4', '5', '2'], '<p>N goes +5 to -3: 8 e<sup>-</sup> gained. Four Zn go 0 to +2: 4 &times; 2 = 8 e<sup>-</sup> lost. Equal, so 8.</p>', 'Check the charge too: left -1 - 7 = -8, right 4 &times; (-2) = -8.'),
    nat('rx-090', 4, 'balancing in base', 'In the balanced equation 4Zn + NO<sub>3</sub><sup>-</sup> + 7OH<sup>-</sup> + xH<sub>2</sub>O &rarr; 4[Zn(OH)<sub>4</sub>]<sup>2-</sup> + NH<sub>3</sub>, find x.', 6, 0, '', '<p>Hydrogen: left 7 + 2x; right 16 (from four Zn(OH)<sub>4</sub>) + 3 = 19. So 7 + 2x = 19, x = <b>6</b>. Check O: left 3 + 7 + 6 = 16; right 4 &times; 4 = 16.</p>', '', () => (19 - 7) / 2),
    msq('rx-091', 4, 'oxidation number of peroxides', 'Which of the following oxoacids of sulphur contain an O-O (peroxide) linkage?', ['H<sub>2</sub>S<sub>2</sub>O<sub>8</sub>', 'H<sub>2</sub>SO<sub>5</sub>', 'H<sub>2</sub>S<sub>2</sub>O<sub>7</sub>', 'H<sub>2</sub>S<sub>2</sub>O<sub>6</sub>'], [0, 1], '<p>H<sub>2</sub>S<sub>2</sub>O<sub>8</sub> (peroxodisulfuric) and H<sub>2</sub>SO<sub>5</sub> (peroxomonosulfuric) have O-O links. H<sub>2</sub>S<sub>2</sub>O<sub>7</sub> (disulfuric) has an S-O-S bridge; H<sub>2</sub>S<sub>2</sub>O<sub>6</sub> (dithionic) has an S-S bond. Sulphur is +6 in the first three and +5 in dithionic acid.</p>'),
    msq('rx-092', 4, 'disproportionation', 'In the reaction of Cl<sub>2</sub> with hot concentrated NaOH, 3Cl<sub>2</sub> + 6OH<sup>-</sup> &rarr; 5Cl<sup>-</sup> + ClO<sub>3</sub><sup>-</sup> + 3H<sub>2</sub>O, which statements are correct?', ['It is a disproportionation reaction', '5 electrons are transferred for every three Cl<sub>2</sub>', 'The n-factor of Cl<sub>2</sub> is 5/3', 'Cl<sub>2</sub> acts only as an oxidising agent'], [0, 1, 2], '<p>Cl is both reduced (0 to -1) and oxidised (0 to +5), so it is a disproportionation. Electrons gained = 5 &times; 1 = 5 = lost. n = 5/3 per Cl<sub>2</sub>. Cl<sub>2</sub> acts as both oxidising and reducing agent, so D is wrong.</p>'),
    P('rx-093', 3, 'redox titrations', 'p1', 'The balanced mole ratio between permanganate and oxalate in acid is', '2MnO<sub>4</sub><sup>-</sup> : 5C<sub>2</sub>O<sub>4</sub><sup>2-</sup>', ['1MnO<sub>4</sub><sup>-</sup> : 1C<sub>2</sub>O<sub>4</sub><sup>2-</sup>', '5MnO<sub>4</sub><sup>-</sup> : 2C<sub>2</sub>O<sub>4</sub><sup>2-</sup>', '1MnO<sub>4</sub><sup>-</sup> : 5C<sub>2</sub>O<sub>4</sub><sup>2-</sup>'], '<p>Mn gains 5 e<sup>-</sup>; each oxalate loses 2 e<sup>-</sup>. LCM = 10, so 2 MnO<sub>4</sub><sup>-</sup> (10 e<sup>-</sup>) react with 5 C<sub>2</sub>O<sub>4</sub><sup>2-</sup> (10 e<sup>-</sup>).</p>'),
    PN('rx-094', 3, 'redox titrations', 'p1', 'Find the number of millimoles of oxalate in the sample.', 2, 0, 'mmol', '<p>mmol MnO<sub>4</sub><sup>-</sup> = 40.0 &times; 0.0200 = 0.800. Oxalate = 0.800 &times; 5/2 = <b>2.00 mmol</b>.</p>', 'Use 5/2, not 2/5.', () => 40 * 0.02 * 5 / 2),
    PN('rx-095', 3, 'redox titrations', 'p1', 'Find the percentage purity of the sodium oxalate.', 80, 0, '%', '<p>Mass of Na<sub>2</sub>C<sub>2</sub>O<sub>4</sub> = 2.00 mmol &times; 134 = 268 mg = 0.268 g.</p><p>Purity = 0.268/0.335 &times; 100 = <b>80 %</b>.</p>', '', () => 2 * 134 / 335 * 100),
    P('rx-096', 4, 'iodometry', 'p2', 'In the reaction 2Cu<sup>2+</sup> + 4I<sup>-</sup> &rarr; 2CuI + I<sub>2</sub>, the iodide ion acts as', 'a reducing agent and also as a precipitating agent', ['only an oxidising agent', 'only a precipitating agent', 'an acid'], '<p>Cu<sup>2+</sup> is reduced to Cu<sup>+</sup> (1 e<sup>-</sup>) by I<sup>-</sup>, which is oxidised to I<sub>2</sub>: a reducing agent. The Cu<sup>+</sup> is held as insoluble CuI, which also drives the reaction: so I<sup>-</sup> is a precipitating agent too.</p>'),
    PN('rx-097', 4, 'iodometry', 'p2', 'Find the percentage of copper in the ore.', 31.8, 0.1, '%', '<p>mmol thiosulfate = 25.0 &times; 0.100 = 2.50. I<sub>2</sub> = 1.25 mmol. Cu<sup>2+</sup> = 2 &times; 1.25 = 2.50 mmol (1 Cu<sup>2+</sup> &equiv; 1 S<sub>2</sub>O<sub>3</sub><sup>2-</sup>).</p><p>Mass Cu = 2.50 &times; 63.5 = 158.75 mg = 0.1588 g. Percentage = 0.1588/0.500 &times; 100 = <b>31.8 %</b>.</p>', '', () => 2.5 * 63.5 / 500 * 100),
    P('rx-098', 4, 'iodometry', 'p2', 'The indicator used and when it is added in this titration are', 'starch, added near the end point when the iodine colour has faded to pale yellow', ['starch, added at the start of the titration', 'KMnO<sub>4</sub> as a self-indicator', 'phenolphthalein, added near the end point'], '<p>Starch forms a deep blue complex with iodine. If added at the start, too much iodine is adsorbed on starch and the end point is sluggish. It is added when the solution is pale yellow; the end point is the disappearance of the blue.</p>'),
    P('rx-099', 3, 'disproportionation', 'p3', 'In cold dilute NaOH the chlorine-containing products are', 'Cl<sup>-</sup> and ClO<sup>-</sup>', ['Cl<sup>-</sup> and ClO<sub>3</sub><sup>-</sup>', 'ClO<sup>-</sup> and ClO<sub>3</sub><sup>-</sup>', 'ClO<sub>3</sub><sup>-</sup> and ClO<sub>4</sub><sup>-</sup>'], '<p>Cold dilute: Cl<sub>2</sub> + 2OH<sup>-</sup> &rarr; Cl<sup>-</sup> + ClO<sup>-</sup> + H<sub>2</sub>O (hypochlorite, bleach). Hot concentrated: chlorate and chloride, since hypochlorite itself disproportionates on heating: 3ClO<sup>-</sup> &rarr; 2Cl<sup>-</sup> + ClO<sub>3</sub><sup>-</sup>.</p>'),
    P('rx-100', 3, 'disproportionation', 'p3', 'In the hot concentrated reaction, the number of electrons lost per mole of ClO<sub>3</sub><sup>-</sup> formed is', '5', ['1', '3', '6'], '<p>Cl goes from 0 in Cl<sub>2</sub> to +5 in ClO<sub>3</sub><sup>-</sup>: 5 e<sup>-</sup> lost per Cl atom, matched by the 5 Cl<sup>-</sup> formed (1 e<sup>-</sup> gained each).</p>'),
    PN('rx-101', 4, 'equivalent weight', 'p3', 'Find the equivalent weight of Cl<sub>2</sub> (M = 71) in the hot concentrated reaction.', 42.6, 0.1, 'g eq<sup>-1</sup>', '<p>For 3Cl<sub>2</sub>, 5 e<sup>-</sup> are exchanged, so n-factor per Cl<sub>2</sub> = 5/3. Equivalent weight = 71 &times; 3/5 = <b>42.6</b>.</p>', 'Different media give different n-factors for the same reactant.', () => 71 * 3 / 5),

    // ---------- Level 5 ----------
    nat('rx-102', 5, 'n-factor', 'Find the n-factor of iron pyrite FeS<sub>2</sub> when it is oxidised to Fe<sup>3+</sup> and SO<sub>4</sub><sup>2-</sup>. (In FeS<sub>2</sub>, iron is +2 and each S is -1.)', 15, 0, '', '<p>Fe: +2 to +3 gives 1 e<sup>-</sup>. Each S: -1 to +6 gives 7 e<sup>-</sup>; two S give 14.</p><p>n = 1 + 14 = <b>15</b>.</p>', 'FeS<sub>2</sub> contains the disulfide ion S<sub>2</sub><sup>2-</sup>, so S is -1, not -2.', () => 1 + 2 * 7),
    nat('rx-103', 5, 'equivalent weight', 'Fe<sub>3</sub>O<sub>4</sub> (M = 232) is oxidised by acidified KMnO<sub>4</sub> completely to Fe<sup>3+</sup>. Find the equivalent weight of Fe<sub>3</sub>O<sub>4</sub>.', 232, 0, 'g eq<sup>-1</sup>', '<p>Fe<sub>3</sub>O<sub>4</sub> = FeO&middot;Fe<sub>2</sub>O<sub>3</sub>: only one Fe is in the +2 state per formula unit, and it goes to +3. n = 1.</p><p>Equivalent weight = 232/1 = <b>232</b>. (Using the average +8/3 gives the same: three Fe each change by 1/3, total 1.)</p>', 'Only the Fe<sup>2+</sup> is oxidised; Fe<sup>3+</sup> is already at +3.', () => 232 / 1),
    nat('rx-104', 5, 'n-factor in different media', 'Find the n-factor of sodium thiosulfate, Na<sub>2</sub>S<sub>2</sub>O<sub>3</sub>, when chlorine water oxidises it to sulphate. (With iodine the product is tetrathionate and n = 1.)', 8, 0, '', '<p>Average S in S<sub>2</sub>O<sub>3</sub><sup>2-</sup> is +2. In SO<sub>4</sub><sup>2-</sup> S is +6. Each S loses 4 e<sup>-</sup>; two S lose 8.</p><p>n = <b>8</b> (vs 1 with I<sub>2</sub>, because iodine is a weaker oxidant).</p>', 'The n-factor depends on the oxidant used.', () => 2 * (6 - 2)),
    nat('rx-105', 5, 'redox titrations', '25.0 mL of a solution containing 0.100 M Fe<sup>2+</sup> and 0.0500 M oxalate (C<sub>2</sub>O<sub>4</sub><sup>2-</sup>) is titrated in acid with 0.0200 M KMnO<sub>4</sub>. Find the volume of KMnO<sub>4</sub> needed in mL.', 50, 0, 'mL', '<p>Fe<sup>2+</sup>: 25.0 &times; 0.100 = 2.50 mmol, n = 1: 2.50 meq.</p><p>Oxalate: 25.0 &times; 0.0500 = 1.25 mmol, n = 2: 2.50 meq. Total = 5.00 meq.</p><p>N(KMnO<sub>4</sub>) = 0.0200 &times; 5 = 0.100 N, so V = 5.00/0.100 = <b>50 mL</b>.</p>', 'Both reductants consume permanganate.', () => (25 * 0.1 * 1 + 25 * 0.05 * 2) / (0.02 * 5)),
    mk('rx-106', 5, 'mixed with disproportionation', 'Cu<sup>+</sup> disproportionates in water: 2Cu<sup>+</sup> &rarr; Cu<sup>2+</sup> + Cu. Given E&deg;(Cu<sup>+</sup>/Cu) = +0.52 V and E&deg;(Cu<sup>2+</sup>/Cu<sup>+</sup>) = +0.16 V, the E&deg;<sub>cell</sub> of this disproportionation is', '+0.36 V', ['-0.36 V', '+0.68 V', '+0.16 V'], '<p>In the disproportionation one Cu<sup>+</sup> is reduced (cathode: Cu<sup>+</sup> + e<sup>-</sup> &rarr; Cu, E&deg; = +0.52 V) and another is oxidised (anode: Cu<sup>+</sup> &rarr; Cu<sup>2+</sup> + e<sup>-</sup>, whose reduction potential is +0.16 V).</p><p>E&deg;<sub>cell</sub> = 0.52 - 0.16 = <b>+0.36 V</b>. Positive, so Cu<sup>+</sup> is unstable in water and disproportionates. (-0.36 V reverses the subtraction; +0.68 V adds the two.)</p>', 'A species disproportionates when E&deg;(right) &gt; E&deg;(left) on the Latimer diagram.'),
    msq('rx-107', 5, 'redox titrations', 'In an iodometric determination of Cu<sup>2+</sup> with excess KI and thiosulfate, which statements are correct?', ['1 mol Cu<sup>2+</sup> liberates 0.5 mol I<sub>2</sub>', '1 mol Cu<sup>2+</sup> corresponds to 1 mol S<sub>2</sub>O<sub>3</sub><sup>2-</sup>', 'The equivalent weight of CuSO<sub>4</sub>&middot;5H<sub>2</sub>O in this reaction equals its molar mass', 'Thiosulfate is oxidised to sulphate by iodine'], [0, 1, 2], '<p>2Cu<sup>2+</sup> + 4I<sup>-</sup> &rarr; 2CuI + I<sub>2</sub>: 1 Cu<sup>2+</sup> gives 0.5 I<sub>2</sub>, which needs 1 S<sub>2</sub>O<sub>3</sub><sup>2-</sup>. Cu<sup>2+</sup> gains 1 e<sup>-</sup> (to Cu<sup>+</sup>), so n = 1 and equivalent weight = M. Iodine oxidises thiosulfate only to tetrathionate, not sulphate.</p>'),
    asr('rx-108', 5, 'oxidation number structures', 'The average oxidation number of sulphur in Na<sub>2</sub>S<sub>2</sub>O<sub>3</sub> is +2, but the two sulphur atoms behave differently in redox reactions.', 'In the thiosulfate ion the central S is +6 and the terminal S is -2.', 0, '<p>Both statements are true and R explains A. Thiosulfate has a sulphate-like central S (+6) with a sulphide-like S (-2) attached; the average is +2. That is why iodine oxidises only the terminal S in forming S<sub>4</sub>O<sub>6</sub><sup>2-</sup> (S-S link between terminal S atoms).</p>'),
    stm('rx-109', 5, 'equivalent weight', 'The equivalent weight of Fe<sub>3</sub>O<sub>4</sub> as a reducing agent (to Fe<sup>3+</sup>) equals its molar mass.', 'The equivalent weight of FeC<sub>2</sub>O<sub>4</sub> as a reducing agent (to Fe<sup>3+</sup> and CO<sub>2</sub>) is one-third of its molar mass.', 0, '<p>I: only one Fe<sup>2+</sup> per Fe<sub>3</sub>O<sub>4</sub>, so n = 1. II: n = 3 for FeC<sub>2</sub>O<sub>4</sub>, so M/3. Both correct.</p>'),
    mk('rx-110', 5, 'mixed with mole concept', 'A 0.500 g sample containing only FeSO<sub>4</sub> (M = 152) and inert salt needs 22.0 mL of 0.0200 M KMnO<sub>4</sub> in acid. The percentage of FeSO<sub>4</sub> in the sample is', '66.9 %', ['13.4 %', '33.4 %', '134 %'], '<p>mmol MnO<sub>4</sub><sup>-</sup> = 22.0 &times; 0.0200 = 0.440. Fe<sup>2+</sup> = 5 &times; 0.440 = 2.20 mmol. Mass FeSO<sub>4</sub> = 2.20 &times; 152 = 334.4 mg = 0.3344 g.</p><p>Percentage = 0.3344/0.500 &times; 100 = <b>66.9 %</b>. (13.4 % forgets the factor 5; 134 % is not possible.)</p>', 'Check that a percentage cannot exceed 100.'),
  ],
  gens: [
    { id: 'rx-g01', type: 'nat', level: 1, exams: EX[1], sub: 'oxidation number',
      make(rng) {
        const r = choose(rng, OXN);
        return { q: `Find the oxidation number of ${r[1]} in ${r[0]}.`, answer: +r[2].toFixed(2), tol: r[2] % 1 === 0 ? 0 : 0.01, v: r[2],
          sol: `<p>Set the sum of oxidation numbers to the charge of the species (zero here). Let ${r[1]} = x: ${r[3]}.</p><p>x = <b>${fmt(r[2], 3)}</b>.</p>` };
      }, verify: (p) => p.v },
    { id: 'rx-g02', type: 'nat', level: 2, exams: EX[2], sub: 'n-factor',
      make(rng) {
        const r = choose(rng, NF);
        return { q: `Find the n-factor of ${r[0]}.`, answer: r[1], tol: 0, n: r[1],
          sol: `<p>${r[2]}.</p><p>n-factor = <b>${r[1]}</b>.</p>` };
      }, verify: (p) => p.n },
    { id: 'rx-g03', type: 'nat', level: 2, exams: EX[2], sub: 'equivalent weight',
      make(rng) {
        const r = choose(rng, NF); const eq = r[3] / r[1];
        return { q: `Find the equivalent weight of ${r[0]} (molar mass ${r[3]} g mol<sup>-1</sup>).`, answer: +eq.toPrecision(4), tol: eq * 0.005, unit: 'g eq<sup>-1</sup>', M: r[3], n: r[1],
          sol: `<p>${r[2]}, so n = ${r[1]}.</p><p>Equivalent weight = M/n = ${r[3]}/${r[1]} = <b>${fmt(eq, 4)}</b>.</p>` };
      }, verify: (p) => p.M / p.n },
    { id: 'rx-g04', type: 'nat', level: 2, exams: EX[2], sub: 'normality',
      make(rng) {
        const M = pick(rng, 1, 9, 1) / 100; const sp = choose(rng, [['KMnO<sub>4</sub> in acid', 5], ['K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub> in acid', 6], ['H<sub>2</sub>C<sub>2</sub>O<sub>4</sub> (oxidised to CO<sub>2</sub>)', 2], ['FeSO<sub>4</sub> (to Fe<sup>3+</sup>)', 1]]);
        const N = M * sp[1];
        return { q: `Find the normality of a ${M} M solution of ${sp[0]}.`, answer: +N.toFixed(3), tol: 0.002, unit: 'N', M, n: sp[1],
          sol: `<p>Normality = molarity &times; n-factor = ${M} &times; ${sp[1]} = <b>${N.toFixed(3)} N</b>.</p>` };
      }, verify: (p) => p.M * p.n },
    { id: 'rx-g05', type: 'nat', level: 3, exams: EX[3], sub: 'redox titrations',
      make(rng) {
        const V1 = pick(rng, 10, 50, 5); const c1 = pick(rng, 1, 5, 1) / 10; const c2 = choose(rng, [0.01, 0.02, 0.04, 0.05]);
        const V2 = V1 * c1 / (5 * c2);
        return { q: `${V1} mL of ${c1} M FeSO<sub>4</sub> is titrated in acid with ${c2} M KMnO<sub>4</sub>. Find the volume of KMnO<sub>4</sub> needed.`, answer: +V2.toPrecision(4), tol: V2 * 0.005, unit: 'mL', V1, c1, c2,
          sol: `<p>MnO<sub>4</sub><sup>-</sup> + 5Fe<sup>2+</sup> + 8H<sup>+</sup> &rarr; Mn<sup>2+</sup> + 5Fe<sup>3+</sup> + 4H<sub>2</sub>O.</p><p>mmol Fe<sup>2+</sup> = ${V1} &times; ${c1} = ${fmt(V1 * c1, 3)}; mmol MnO<sub>4</sub><sup>-</sup> = ${fmt(V1 * c1 / 5, 3)}.</p><p>V = ${fmt(V1 * c1 / 5, 3)}/${c2} = <b>${fmt(V2, 4)} mL</b>.</p>` };
      }, verify: (p) => (p.V1 * p.c1 * 1) / (p.c2 * 5) },
    { id: 'rx-g06', type: 'nat', level: 3, exams: EX[3], sub: 'redox titrations',
      make(rng) {
        const V1 = pick(rng, 10, 40, 5); const c1 = pick(rng, 1, 4, 1) / 10; const c2 = choose(rng, [0.01, 0.02, 0.04, 0.05]);
        const V2 = V1 * c1 * 2 / (5 * c2);
        return { q: `${V1} mL of ${c1} M oxalic acid is titrated in hot dilute H<sub>2</sub>SO<sub>4</sub> with ${c2} M KMnO<sub>4</sub>. Find the volume of KMnO<sub>4</sub> needed.`, answer: +V2.toPrecision(4), tol: V2 * 0.005, unit: 'mL', V1, c1, c2,
          sol: `<p>2MnO<sub>4</sub><sup>-</sup> + 5C<sub>2</sub>O<sub>4</sub><sup>2-</sup> + 16H<sup>+</sup> &rarr; 2Mn<sup>2+</sup> + 10CO<sub>2</sub> + 8H<sub>2</sub>O.</p><p>mmol oxalate = ${fmt(V1 * c1, 3)}; mmol MnO<sub>4</sub><sup>-</sup> = ${fmt(V1 * c1, 3)} &times; 2/5 = ${fmt(V1 * c1 * 0.4, 3)}.</p><p>V = ${fmt(V1 * c1 * 0.4, 3)}/${c2} = <b>${fmt(V2, 4)} mL</b>.</p>` };
      }, verify: (p) => (p.V1 * p.c1 * 2) / 1 / (p.c2 * 5) },
    { id: 'rx-g07', type: 'nat', level: 3, exams: EX[3], sub: 'equivalent weight and mass',
      make(rng) {
        const N = choose(rng, [0.05, 0.1, 0.2]); const V = choose(rng, [100, 250, 500, 1000]); const sp = choose(rng, [['KMnO<sub>4</sub> (acidic)', 158, 5], ['K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub> (acidic)', 294, 6], ['oxalic acid H<sub>2</sub>C<sub>2</sub>O<sub>4</sub>', 90, 2]]);
        const m = N * (V / 1000) * sp[1] / sp[2];
        return { q: `What mass of ${sp[0]} (M = ${sp[1]}) is needed to prepare ${V} mL of ${N} N solution for redox use?`, answer: +m.toPrecision(4), tol: m * 0.005, unit: 'g', N, V, M: sp[1], n: sp[2],
          sol: `<p>Equivalent weight = ${sp[1]}/${sp[2]} = ${fmt(sp[1] / sp[2], 4)}.</p><p>Equivalents = ${N} &times; ${V / 1000} L = ${fmt(N * V / 1000, 3)}. Mass = ${fmt(N * V / 1000, 3)} &times; ${fmt(sp[1] / sp[2], 4)} = <b>${fmt(m, 4)} g</b>.</p>` };
      }, verify: (p) => p.N * p.V / 1000 * p.M / p.n },
    { id: 'rx-g08', type: 'nat', level: 3, exams: EX[3], sub: 'iodometry',
      make(rng) {
        const V = pick(rng, 10, 40, 2.5); const c = choose(rng, [0.05, 0.1, 0.2]);
        const mg = V * c * 63.5;
        return { q: `Copper(II) in a sample is treated with excess KI, and the iodine released needs ${V} mL of ${c} M Na<sub>2</sub>S<sub>2</sub>O<sub>3</sub>. Find the mass of copper in the sample in mg (Cu = 63.5).`, answer: +mg.toPrecision(4), tol: mg * 0.005, unit: 'mg', V, c,
          sol: `<p>2Cu<sup>2+</sup> + 4I<sup>-</sup> &rarr; 2CuI + I<sub>2</sub> and I<sub>2</sub> + 2S<sub>2</sub>O<sub>3</sub><sup>2-</sup> &rarr; 2I<sup>-</sup> + S<sub>4</sub>O<sub>6</sub><sup>2-</sup>, so 1 Cu<sup>2+</sup> &equiv; 1 S<sub>2</sub>O<sub>3</sub><sup>2-</sup>.</p><p>mmol Cu = ${V} &times; ${c} = ${fmt(V * c, 4)}. Mass = ${fmt(V * c, 4)} &times; 63.5 = <b>${fmt(mg, 4)} mg</b>.</p>` };
      }, verify: (p) => p.V * p.c * 63.5 },
    { id: 'rx-g09', type: 'nat', level: 3, exams: EX[3], sub: 'electrochemical series',
      make(rng) {
        const ox = choose(rng, [['Zn', -0.76], ['Fe', -0.44], ['Mg', -2.37], ['Ni', -0.25]]); const red = choose(rng, [['Cu<sup>2+</sup>', 0.34], ['Ag<sup>+</sup>', 0.80], ['Br<sub>2</sub>', 1.09]]);
        const E = red[1] - ox[1];
        return { q: `Find E&deg;<sub>cell</sub> (in V) for the reaction in which ${ox[0]} (E&deg; for its ion/metal = ${ox[1]} V) reduces ${red[0]} (E&deg; = +${red[1]} V).`, answer: +E.toFixed(2), tol: 0.011, unit: 'V', a: ox[1], b: red[1],
          sol: `<p>E&deg;<sub>cell</sub> = E&deg;(reduction) - E&deg;(oxidation) = ${red[1]} - (${ox[1]}) = <b>${E.toFixed(2)} V</b>. It is positive, so the reaction is spontaneous.</p>` };
      }, verify: (p) => p.b - p.a },
    { id: 'rx-g10', type: 'nat', level: 3, exams: EX[3], sub: 'electrochemical series',
      make(rng) {
        const n = choose(rng, [1, 2, 3, 4]); const E = pick(rng, 3, 15, 1) / 10;
        const dG = -n * 96500 * E / 1000;
        return { q: `A cell reaction transfers ${n} electron${n > 1 ? 's' : ''} and has E&deg;<sub>cell</sub> = ${E} V. Find &Delta;G&deg; in kJ mol<sup>-1</sup>. (F = 96500 C mol<sup>-1</sup>)`, answer: +dG.toFixed(1), tol: Math.abs(dG) * 0.005, unit: 'kJ mol<sup>-1</sup>', n, E,
          sol: `<p>&Delta;G&deg; = -nFE&deg; = -${n} &times; 96500 &times; ${E} = ${fmt(-n * 96500 * E, 5)} J = <b>${dG.toFixed(1)} kJ</b>.</p>` };
      }, verify: (p) => -p.n * 96500 * p.E / 1000 },
    { id: 'rx-g11', type: 'nat', level: 3, exams: EX[3], sub: 'equivalent weight',
      make(rng) {
        const vol = pick(rng, 5, 30, 5); const M = vol * 2 / 22.4;
        return { q: `A hydrogen peroxide solution is labelled &ldquo;${vol} volume&rdquo; (1 mL gives ${vol} mL O<sub>2</sub> at STP on decomposition). Find its molarity.`, answer: +M.toPrecision(3), tol: M * 0.01, unit: 'M', vol,
          sol: `<p>2H<sub>2</sub>O<sub>2</sub> &rarr; 2H<sub>2</sub>O + O<sub>2</sub>. 1 L gives ${vol} L O<sub>2</sub> = ${vol}/22.4 = ${fmt(vol / 22.4, 3)} mol O<sub>2</sub>.</p><p>H<sub>2</sub>O<sub>2</sub> = 2 &times; ${fmt(vol / 22.4, 3)} = <b>${fmt(M, 3)} M</b>.</p>` };
      }, verify: (p) => p.vol / 11.2 },
    { id: 'rx-g12', type: 'nat', level: 4, exams: EX[4], sub: 'redox titrations',
      make(rng) {
        const m = pick(rng, 0.2, 0.6, 0.05); const V = pick(rng, 15, 30, 1); const c = choose(rng, [0.02, 0.04]);
        const mmol = V * c * 5; const mass = mmol * 152 / 1000; const pc = mass / m * 100;
        if (pc > 99) return this.make(rng);
        return { q: `A ${m} g sample containing FeSO<sub>4</sub> (M = 152) and inert matter needs ${V} mL of ${c} M KMnO<sub>4</sub> in acid. Find the percentage of FeSO<sub>4</sub>.`, answer: +pc.toPrecision(3), tol: pc * 0.01, unit: '%', m, V, c,
          sol: `<p>mmol MnO<sub>4</sub><sup>-</sup> = ${V} &times; ${c} = ${fmt(V * c, 3)}; Fe<sup>2+</sup> = 5 &times; ${fmt(V * c, 3)} = ${fmt(mmol, 3)} mmol.</p><p>Mass FeSO<sub>4</sub> = ${fmt(mmol, 3)} &times; 152 = ${fmt(mmol * 152, 4)} mg = ${fmt(mass, 3)} g. Percentage = ${fmt(mass, 3)}/${m} &times; 100 = <b>${fmt(pc, 3)} %</b>.</p>` };
      }, verify: (p) => p.V * p.c * 5 * 152 / 1000 / p.m * 100 },
    { id: 'rx-g13', type: 'mcq', level: 2, exams: EX[2], sub: 'oxidising and reducing agents',
      make(rng) {
        const R = [
          ['Zn + CuSO<sub>4</sub> &rarr; ZnSO<sub>4</sub> + Cu', 'CuSO<sub>4</sub>', 'Zn', 'ZnSO<sub>4</sub>', 'Cu', 'Cu goes from +2 to 0 (reduced) and Zn from 0 to +2 (oxidised).'],
          ['Fe<sub>2</sub>O<sub>3</sub> + 3CO &rarr; 2Fe + 3CO<sub>2</sub>', 'Fe<sub>2</sub>O<sub>3</sub>', 'CO', 'CO<sub>2</sub>', 'Fe', 'Fe goes from +3 to 0 (reduced) and C from +2 to +4 (oxidised).'],
          ['Cl<sub>2</sub> + 2KI &rarr; 2KCl + I<sub>2</sub>', 'Cl<sub>2</sub>', 'KI', 'KCl', 'I<sub>2</sub>', 'Cl goes from 0 to -1 (reduced) and I from -1 to 0 (oxidised).'],
          ['H<sub>2</sub> + CuO &rarr; Cu + H<sub>2</sub>O', 'CuO', 'H<sub>2</sub>', 'H<sub>2</sub>O', 'Cu', 'Cu goes from +2 to 0 (reduced) and H from 0 to +1 (oxidised).'],
        ];
        const r = choose(rng, R); const askOx = rng() < 0.5;
        const right = askOx ? r[1] : r[2]; const wrongs = askOx ? [r[2], r[3], r[4]] : [r[1], r[3], r[4]];
        const o = shuffleOpts(rng, right, wrongs);
        return { q: `In the reaction ${r[0]}, the ${askOx ? 'oxidising' : 'reducing'} agent is`, options: o.options, answer: o.answer,
          sol: `<p>${r[5]}</p><p>The ${askOx ? 'oxidising agent is the substance that is reduced' : 'reducing agent is the substance that is oxidised'}: <b>${right}</b>.</p>` };
      } },
    { id: 'rx-g14', type: 'mcq', level: 3, exams: EX[3], sub: 'n-factor',
      make(rng) {
        const r = choose(rng, NF.filter((x) => x[1] !== 1)); const n = r[1];
        const o = numOpts(rng, n, [n + 1, n - 1 > 0 ? n - 1 : n + 3, n * 2], '', 3);
        return { q: `The n-factor of ${r[0]} is`, options: o.options, answer: o.answer,
          sol: `<p>${r[2]}.</p><p>n-factor = <b>${n}</b>. The other values come from counting only one atom, or counting the wrong change.</p>` };
      } },
  ],
};
